fn main() {
    let s = "ab";
    print(str_len(s));
    let total = 0;
    for i in range(0, 3) {
        let t = s;
        total = total + str_len(t);
    }
    print(total);
}

fn main() {
    let mut v = push(push(vec(), 1), 2);
    print(len(v));
    for x in v {
        v = push(v, x);
    }
    print(len(v));
}

